/**
 * `tsc --noEmit` for CI and local checks.
 * next-env.d.ts is generated by Next and gitignored, so create the stub
 * when this runs on a fresh checkout.
 */
import { createRequire } from "node:module";
import { spawnSync } from "node:child_process";
import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const require = createRequire(import.meta.url);
const nextEnv = path.join(root, "next-env.d.ts");

if (!fs.existsSync(nextEnv)) {
  fs.writeFileSync(
    nextEnv,
    [
      '/// <reference types="next" />',
      '/// <reference types="next/image-types/global" />',
      "",
      "// NOTE: This file should not be edited",
      "// see https://nextjs.org/docs/app/api-reference/config/typescript for more information.",
      "",
    ].join("\n"),
  );
}

const tsc = require.resolve("typescript/bin/tsc");
const result = spawnSync(process.execPath, [tsc, "--noEmit", "--pretty", "false"], {
  cwd: root,
  stdio: "inherit",
});
process.exit(result.status === null ? 1 : result.status);
